import React from "react";
import { AppProvider } from "./context/AppContext";
import EarthViewer from "./components/EarthViewer";
import ControlPanel from "./components/ControlPanel";
import CountryInfo from "./components/CountryInfo";
import SettingsPanel from "./components/SettingsPanel";
import KeyboardShortcuts from "./components/KeyboardShortcuts";
import "./App.css";

function App() {
  return (
    <AppProvider>
      <div className="App relative w-full h-screen overflow-hidden bg-space-dark">
        {/* Keyboard shortcuts handler */}
        <KeyboardShortcuts />

        {/* Main Earth Viewer */}
        <EarthViewer />

        {/* UI Overlays */}
        <ControlPanel />
        <CountryInfo />
        <SettingsPanel />

        {/* Help Badge */}
        <div className="absolute bottom-4 left-4 text-xs text-gray-400 bg-black bg-opacity-50 px-3 py-2 rounded-lg">
          <div className="font-medium">Interactive Earth Viewer</div>
          <div className="text-gray-500">
            Mouse: Rotate • Scroll: Zoom • Click: Select Country
          </div>
          <div className="text-gray-500 mt-1">
            Shortcuts: C (Controls) • S (Settings) • R (Record) • F (Fullscreen)
            • Space (Pause)
          </div>
        </div>
      </div>
    </AppProvider>
  );
}

export default App;
